file_editor: {"command": "create", "path": "<local-workspace>", "file_text": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>Virtual Spread Plate Lab</title>
<style>
  :root {
    --bg: #0f2027;
    --bg2: #203a43;
    --panel: #1b2d3a;
    --panel-light: #243b4a;
    --ink: #eaf2f5;
    --ink-dim: #9fb3bd;
    --accent: #4ad6c4;
    --accent-2: #7cc4ff;
    --warn: #ffb347;
    --danger: #ff6b6b;
    --good: #69db7c;
    --amber: #ffcf4a;
    --line: #34505f;
  }
  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
  html, body {
    margin: 0; padding: 0;
    background: linear-gradient(135deg, var(--bg), var(--bg2));
    color: var(--ink);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    min-height: 100vh;
    -webkit-font-smoothing: antialiased;
    touch-action: manipulation;
  }
  #lab-root {
    max-width: 1100px;
    margin: 0 auto;
    padding: 14px 14px 40px;
  }
  header h1 {
    margin: 4px 0 2px;
    font-size: clamp(20px, 5vw, 28px);
    letter-spacing: .5px;
  }
  header .sub {
    color: var(--ink-dim);
    font-size: 13px;
    margin: 0 0 10px;
  }

  /* Progress bar */
  .progress-wrap {
    display: flex; align-items: center; gap: 10px;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 8px 12px;
    margin-bottom: 12px;
  }
  .progress-track {
    flex: 1 1 auto;
    height: 10px;
    background: #0c1a22;
    border-radius: 6px;
    overflow: hidden;
  }
  .progress-fill {
    height: 100%; width: 0%;
    background: linear-gradient(90deg, var(--accent), var(--accent-2));
    border-radius: 6px;
    transition: width .5s ease;
  }
  .progress-label { font-size: 13px; color: var(--ink-dim); white-space: nowrap; }

  /* Layout */
  .stage {
    position: relative;
    background: linear-gradient(180deg, #1d3340, #15252f);
    border: 1px solid var(--line);
    border-radius: 14px;
    overflow: hidden;
    margin-bottom: 12px;
  }
  .bench {
    position: relative;
    width: 100%;
    height: clamp(300px, 46vh, 460px);
    background:
      linear-gradient(180deg, rgba(255,255,255,0.02), rgba(0,0,0,0.18)),
      repeating-linear-gradient(90deg, #2a4435 0 4px, #284130 4px 8px);
    border-top: 3px solid #3f6b4e;
  }
  .sterile-zone {
    position: absolute;
    left: 18%; right: 18%;
    top: 30%; bottom: 8%;
    border: 2px dashed rgba(122, 196, 255, 0.35);
    border-radius: 10px;
    background: rgba(124, 196, 255, 0.05);
    display: flex; align-items: flex-end; justify-content: center;
    pointer-events: none;
  }
  .sterile-zone .zone-label {
    position: absolute; top: 6px; left: 50%; transform: translateX(-50%);
    font-size: 11px; color: rgba(122,196,255,.7); letter-spacing: 1px;
  }

  .tray {
    position: absolute;
    top: 8px; bottom: 8px;
    width: 16%;
    display: flex; flex-direction: column; align-items: center; justify-content: space-around;
    gap: 6px;
  }
  .tray.left { left: 8px; }
  .tray.right { right: 8px; }
  .tray .slot-label {
    font-size: 10px; color: var(--ink-dim); text-align: center; margin-top: 2px;
  }

  .equipment {
    position: relative;
    user-select: none;
    touch-action: none;
    cursor: grab;
    transition: filter .15s, transform .15s;
    will-change: transform;
  }
  .equipment:hover { filter: drop-shadow(0 0 6px rgba(74,214,196,.6)); }
  .equipment.dragging { cursor: grabbing; filter: drop-shadow(0 6px 10px rgba(0,0,0,.5)); z-index: 50; }
  .equipment .eq-label {
    display: block; text-align: center; font-size: 10px;
    color: var(--ink-dim); margin-top: 2px;
  }
  .equipment.active { filter: drop-shadow(0 0 8px var(--accent)); }
  .equipment.done { filter: drop-shadow(0 0 6px var(--good)); }

  .drop-target { outline: 2px solid transparent; border-radius: 12px; }
  .drop-target.hover { outline-color: var(--accent); background: rgba(74,214,196,.08); }

  /* Instruction + feedback */
  .info-row {
    display: grid; grid-template-columns: 1fr; gap: 10px;
  }
  @media (min-width: 720px) {
    .info-row { grid-template-columns: 2fr 1fr; }
  }
  .card {
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 12px 14px;
  }
  .step-title { font-size: 13px; color: var(--accent); text-transform: uppercase; letter-spacing: 1px; }
  .step-instruction { font-size: 15px; margin: 6px 0 10px; line-height: 1.45; }
  .feedback {
    min-height: 22px; font-size: 14px; line-height: 1.4;
    border-left: 3px solid var(--line); padding-left: 10px;
    color: var(--ink-dim);
  }
  .feedback.ok { border-color: var(--good); color: var(--good); }
  .feedback.err { border-color: var(--danger); color: #ffb4b4; }

  .why-box { font-size: 13px; color: var(--ink-dim); line-height: 1.5; }
  .why-box h3 { margin: 0 0 6px; font-size: 13px; color: var(--amber); }

  /* Action buttons */
  .actions {
    display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px;
    margin-top: 10px;
  }
  @media (min-width: 560px) { .actions { grid-template-columns: repeat(3, 1fr); } }
  .btn {
    appearance: none; border: 1px solid var(--line);
    background: var(--panel-light); color: var(--ink);
    border-radius: 10px; padding: 12px 8px; font-size: 14px; cursor: pointer;
    transition: background .15s, border-color .15s, transform .05s;
    text-align: center;
  }
  .btn:hover { background: #2c4a5c; border-color: var(--accent); }
  .btn:active { transform: translateY(1px); }
  .btn[disabled] { opacity: .4; cursor: not-allowed; }
  .btn.primary { background: linear-gradient(135deg, #1f6f63, #2a8c7c); border-color: var(--accent); }
  .btn.primary:hover { background: linear-gradient(135deg, #268a7a, #34a08e); }
  .btn.reset { background: #3a2434; border-color: var(--danger); }
  .btn.reset:hover { background: #4a2c40; }

  .btn-row { display: flex; justify-content: flex-end; margin-top: 8px; }

  /* Enhancement: quiz + growth */
  .enhance {
    display: grid; grid-template-columns: 1fr; gap: 12px; margin-top: 12px;
  }
  @media (min-width: 720px) { .enhance { grid-template-columns: 1fr 1fr; } }
  .quiz-q { margin-bottom: 10px; }
  .quiz-q .q { font-size: 13px; margin-bottom: 4px; }
  .quiz-opts { display: flex; flex-wrap: wrap; gap: 6px; }
  .quiz-opt {
    border: 1px solid var(--line); background: var(--panel-light);
    color: var(--ink); border-radius: 8px; padding: 6px 10px; font-size: 13px; cursor: pointer;
  }
  .quiz-opt:hover { border-color: var(--accent); }
  .quiz-opt.correct { border-color: var(--good); color: var(--good); background: rgba(105,219,124,.12); }
  .quiz-opt.wrong { border-color: var(--danger); color: #ffb4b4; background: rgba(255,107,107,.12); }
  .quiz-score { font-size: 13px; color: var(--ink-dim); }

  .contam-meter { display:flex; align-items:center; gap:8px; font-size:12px; color:var(--ink-dim); }
  .contam-bar { flex:1; height:8px; background:#0c1a22; border-radius:5px; overflow:hidden; }
  .contam-fill { height:100%; width:0%; background:linear-gradient(90deg,var(--good),var(--warn),var(--danger)); transition:width .4s; }

  footer { text-align:center; color:var(--ink-dim); font-size:11px; margin-top:18px; }

  .hidden { display: none !important; }
</style>
</head>
<body>
<div id="lab-root" data-testid="lab-root" data-step="sterilize">
  <header>
    <h1>🧫 Virtual Spread Plate Lab</h1>
    <p class="sub">Aseptic technique — spread plate method for yeast culture</p>
  </header>

  <div class="progress-wrap" data-testid="progress">
    <span class="progress-label" id="progress-text">Step 1 of 6</span>
    <div class="progress-track"><div class="progress-fill" id="progress-fill"></div></div>
  </div>

  <div class="stage">
    <div class="bench" id="bench">
      <div class="sterile-zone drop-target" id="sterile-zone" data-testid="equipment-clean-bench">
        <span class="zone-label">STERILE WORK AREA</span>
      </div>

      <div class="tray left">
        <div class="equipment" data-testid="equipment-inoculation-loop" data-action="drag-loop" draggable="true" id="loop" style="touch-action:none;">
          <!-- Inoculation loop SVG -->
          <svg width="64" height="120" viewBox="0 0 64 120" aria-label="Inoculation loop">
            <defs>
              <linearGradient id="metal" x1="0" x2="1">
                <stop offset="0" stop-color="#cfd6da"/><stop offset=".5" stop-color="#8b949a"/><stop offset="1" stop-color="#5a6166"/>
              </linearGradient>
            </defs>
            <rect x="29" y="40" width="6" height="78" rx="3" fill="url(#metal)" stroke="#3a3f43" stroke-width="1"/>
            <rect x="27" y="2" width="10" height="42" rx="5" fill="#6b4a2a" stroke="#4a3318" stroke-width="1"/>
            <circle cx="32" cy="14" r="5.5" fill="none" stroke="#9aa0a4" stroke-width="2.2"/>
            <path id="loop-wire" d="M32 19 q-9 -3 -9 6 q0 9 9 6" fill="none" stroke="#b8bdc1" stroke-width="2"/>
          </svg>
          <span class="eq-label">Inoculation loop</span>
        </div>

        <div class="equipment" data-testid="equipment-alcohol-lamp" data-action="drag-lamp" draggable="true" id="lamp" style="touch-action:none;">
          <!-- Alcohol lamp SVG with flame + warning -->
          <svg width="80" height="120" viewBox="0 0 80 120" aria-label="Alcohol lamp">
            <defs>
              <radialGradient id="flame" cx=".5" cy="1" r="1">
                <stop offset="0" stop-color="#fff7c2"/><stop offset=".4" stop-color="#ffb347"/><stop offset="1" stop-color="#3a7bd5" stop-opacity="0"/>
              </radialGradient>
              <linearGradient id="glass" x1="0" x2="1">
                <stop offset="0" stop-color="#d8e6ef"/><stop offset=".5" stop-color="#9fc2d4"/><stop offset="1" stop-color="#6f97aa"/>
              </linearGradient>
              <linearGradient id="liquid" x1="0" x2="0" y1="0" y2="1">
                <stop offset="0" stop-color="#bfe3f2"/><stop offset="1" stop-color="#7fb8d6"/>
              </linearGradient>
            </defs>
            <!-- flame -->
            <path id="lamp-flame" d="M40 8 C30 26, 48 30, 40 48 C33 34, 35 22, 40 8 Z" fill="url(#flame)" opacity="0.95"/>
            <ellipse cx="40" cy="50" rx="7" ry="4" fill="#2b4d6b" opacity=".5"/>
            <!-- wick -->
            <rect x="38.5" y="46" width="3" height="14" fill="#3a2a1a"/>
            <!-- cap -->
            <rect x="30" y="58" width="20" height="10" rx="3" fill="#7a8b93" stroke="#4a5660"/>
            <!-- body -->
            <path d="M22 68 Q22 64 26 64 L54 64 Q58 64 58 68 L58 96 Q58 108 40 108 Q22 108 22 96 Z" fill="url(#glass)" stroke="#4a6273" stroke-width="1.5"/>
            <path d="M24 90 Q24 102 40 102 Q56 102 56 90 L56 84 Q40 92 24 84 Z" fill="url(#liquid)" opacity="0.85"/>
            <!-- warning badge -->
            <g transform="translate(54,98)">
              <polygon points="0,-12 12,8 -12,8" fill="#ffcf4a" stroke="#7a5b00" stroke-width="1"/>
              <text x="0" y="3" text-anchor="middle" font-size="10" font-weight="700" fill="#5a3b00">!</text>
            </g>
          </svg>
          <span class="eq-label" style="color:var(--warn)">⚠ Flammable</span>
        </div>
      </div>

      <div class="tray right">
        <div class="equipment" data-testid="equipment-yeast-broth" data-action="drag-broth" draggable="true" id="broth" style="touch-action:none;">
          <!-- Test tube with yeast culture broth + cotton plug -->
          <svg width="46" height="120" viewBox="0 0 46 120" aria-label="Yeast culture broth test tube">
            <defs>
              <linearGradient id="broth-grad" x1="0" x2="0" y1="0" y2="1">
                <stop offset="0" stop-color="#f0d488"/><stop offset="1" stop-color="#c79a3e"/>
              </linearGradient>
              <linearGradient id="tube-glass" x1="0" x2="1">
                <stop offset="0" stop-color="#eaf6f6"/><stop offset=".5" stop-color="#bfe0e0"/><stop offset="1" stop-color="#8fc2c2"/>
              </linearGradient>
            </defs>
            <!-- cotton plug -->
            <ellipse id="cotton-plug-svg" cx="23" cy="10" rx="11" ry="7" fill="#f3efe6" stroke="#cdbfa6"/>
            <path d="M12 10 q11 -8 22 0" fill="#fbf8f1" stroke="#d8cdb6"/>
            <!-- tube body -->
            <path d="M14 16 L14 96 Q14 110 23 110 Q32 110 32 96 L32 16 Z" fill="url(#tube-glass)" stroke="#5f9090" stroke-width="1.5" opacity="0.92"/>
            <!-- broth -->
            <path d="M15 50 L15 96 Q15 108 23 108 Q31 108 31 96 L31 50 Z" fill="url(#broth-grad)" opacity="0.9"/>
            <!-- yeast specks -->
            <circle cx="20" cy="70" r="1.4" fill="#8a6a20"/>
            <circle cx="25" cy="82" r="1.2" fill="#8a6a20"/>
            <circle cx="22" cy="92" r="1.5" fill="#8a6a20"/>
            <circle cx="27" cy="64" r="1" fill="#8a6a20"/>
            <!-- glass highlight -->
            <rect x="16" y="22" width="3" height="60" rx="1.5" fill="#fff" opacity="0.35"/>
          </svg>
          <span class="eq-label">Yeast broth</span>
        </div>

        <div class="equipment" data-testid="equipment-agar-plate" data-action="drag-plate" draggable="true" id="plate" style="touch-action:none;">
          <!-- Agar plate (petri dish) SVG -->
          <svg width="120" height="60" viewBox="0 0 120 60" aria-label="Agar plate">
            <defs>
              <radialGradient id="agar" cx=".5" cy=".5" r=".6">
                <stop offset="0" stop-color="#d9605a"/><stop offset=".7" stop-color="#b8443b"/><stop offset="1" stop-color="#8c2f28"/>
              </radialGradient>
              <linearGradient id="lid" x1="0" x2="0" y1="0" y2="1">
                <stop offset="0" stop-color="#eaf6f6" stop-opacity="0.5"/><stop offset="1" stop-color="#bfe0e0" stop-opacity="0.25"/>
              </linearGradient>
            </defs>
            <ellipse cx="60" cy="34" rx="52" ry="20" fill="#bfe0e0" stroke="#5f9090" stroke-width="1.5"/>
            <ellipse cx="60" cy="32" rx="48" ry="17" fill="url(#agar)"/>
            <ellipse id="colonies-layer" cx="60" cy="32" rx="48" ry="17" fill="transparent"/>
            <ellipse cx="60" cy="30" rx="50" ry="18" fill="url(#lid)"/>
          </svg>
          <span class="eq-label">Agar plate</span>
        </div>

        <div class="equipment" data-testid="equipment-cotton-plug" data-action="drag-cotton" draggable="true" id="cotton" style="touch-action:none;">
          <!-- Standalone cotton plug SVG -->
          <svg width="50" height="60" viewBox="0 0 50 60" aria-label="Cotton plug">
            <ellipse cx="25" cy="30" rx="20" ry="18" fill="#f3efe6" stroke="#cdbfa6" stroke-width="1.2"/>
            <path d="M8 28 q17 -14 34 0 q-17 10 -34 0" fill="#fbf8f1" stroke="#d8cdb6"/>
            <circle cx="18" cy="24" r="2" fill="#e7ddc8"/>
            <circle cx="30" cy="32" r="2.5" fill="#e7ddc8"/>
            <circle cx="24" cy="20" r="1.6" fill="#e7ddc8"/>
          </svg>
          <span class="eq-label">Cotton plug</span>
        </div>
      </div>
    </div>
  </div>

  <div class="info-row">
    <div class="card">
      <div class="step-title" id="step-title">Step 1 — Sterilize</div>
      <div class="step-instruction" data-testid="step-instruction" id="step-instruction">
        Sterilize the inoculation loop in the alcohol lamp flame until red-hot.
      </div>
      <div class="feedback" data-testid="feedback" id="feedback">Drag the loop to the flame, or use the buttons below.</div>

      <div class="contam-meter" style="margin-top:8px;">
        <span>Contamination risk</span>
        <div class="contam-bar"><div class="contam-fill" id="contam-fill" style="width:15%"></div></div>
        <span id="contam-pct">15%</span>
      </div>

      <div class="actions" id="actions">
        <button class="btn primary" data-action="sterilize">🔥 Sterilize loop</button>
        <button class="btn" data-action="cool" disabled>❄️ Cool loop</button>
        <button class="btn" data-action="sample" disabled>🧪 Sample culture</button>
        <button class="btn" data-action="inoculate" disabled>🦠 Inoculate plate</button>
        <button class="btn" data-action="spread" disabled>↔️ Spread sample</button>
        <button class="btn" data-action="incubate" disabled>🌡️ Incubate</button>
      </div>
      <div class="btn-row">
        <button class="btn reset" data-action="reset" id="reset-btn">↻ Reset</button>
      </div>
    </div>

    <div class="card why-box" id="why-box">
      <h3>Why this step matters</h3>
      <p id="why-text">Flaming the loop incinerates any microbes on the wire, so you don't introduce contamination when you touch the culture.</p>
    </div>
  </div>

  <div class="enhance">
    <div class="card" id="growth-card">
      <h3 style="margin:0 0 6px;color:var(--accent);font-size:14px;">🔬 Time-lapse colony growth</h3>
      <p style="font-size:13px;color:var(--ink-dim);margin:0 0 8px;" id="growth-status">Complete the experiment to watch colonies grow.</p>
      <div id="growth-controls" class="hidden">
        <button class="btn primary" id="timelapse-btn" data-action="timelapse">▶ Play time-lapse</button>
      </div>
    </div>

    <div class="card" id="quiz-card">
      <h3 style="margin:0 0 8px;color:var(--amber);font-size:14px;">📝 Quick check</h3>
      <div id="quiz-area"></div>
      <div class="quiz-score" id="quiz-score"></div>
    </div>
  </div>

  <footer>Virtual Spread Plate Lab · Original SVG artwork · No external assets</footer>
</div>

<script>
(function () {
  "use strict";

  var STEP_ORDER = ["sterilize", "cool", "sample", "inoculate", "spread", "incubate", "complete"];

  var STEP_META = {
    sterilize: {
      title: "Step 1 — Sterilize",
      instruction: "Sterilize the inoculation loop in the alcohol lamp flame until red-hot.",
      why: "Flaming the loop incinerates any microbes on the wire, so you don't introduce contamination when you touch the culture.",
      actionLabel: "🔥 Sterilize loop"
    },
    cool: {
      title: "Step 2 — Cool",
      instruction: "Cool the sterilized loop by holding it briefly in the sterile work area.",
      why: "A red-hot loop would kill the yeast you're trying to culture. Letting it cool prevents splattering and cell death.",
      actionLabel: "❄️ Cool loop"
    },
    sample: {
      title: "Step 3 — Sample",
      instruction: "Dip the cooled, sterile loop into the yeast culture broth to pick up cells.",
      why: "The loop carries a thin film of liquid. A sterile loop ensures only the intended yeast is transferred.",
      actionLabel: "🧪 Sample culture"
    },
    inoculate: {
      title: "Step 4 — Inoculate",
      instruction: "Touch the loaded loop to the agar surface to deposit the yeast sample.",
      why: "You place a small drop on the agar so it can be spread evenly in the next step.",
      actionLabel: "🦠 Inoculate plate"
    },
    spread: {
      title: "Step 5 — Spread",
      instruction: "Spread the sample evenly across the agar surface using the loop.",
      why: "Even spreading separates cells so they grow into isolated colonies you can count — the whole point of a spread plate.",
      actionLabel: "↔️ Spread sample"
    },
    incubate: {
      title: "Step 6 — Incubate",
      instruction: "Place the plate in the incubator and let the colonies grow.",
      why: "At the right temperature, each viable yeast cell multiplies into a visible colony. Incubation time lets you count results.",
      actionLabel: "🌡️ Incubate"
    },
    complete: {
      title: "Complete",
      instruction: "Experiment complete! Review your results and the time-lapse growth below.",
      why: "Well-separated colonies mean good aseptic technique. Overlapping colonies suggest poor spreading or contamination.",
      actionLabel: ""
    }
  };

  var state = {
    step: "sterilize",
    completed: false,
    history: [],
    contam: 15,
    loopSterile: false,
    loopHot: false,
    loopLoaded: false,
    plateInoculated: false,
    plateSpread: false
  };

  var root = document.getElementById("lab-root");
  var elStepTitle = document.getElementById("step-title");
  var elInstruction = document.getElementById("step-instruction");
  var elFeedback = document.getElementById("feedback");
  var elProgressFill = document.getElementById("progress-fill");
  var elProgressText = document.getElementById("progress-text");
  var elWhyText = document.getElementById("why-text");
  var elContamFill = document.getElementById("contam-fill");
  var elContamPct = document.getElementById("contam-pct");
  var elGrowthStatus = document.getElementById("growth-status");
  var elGrowthControls = document.getElementById("growth-controls");
  var elLampFlame = document.getElementById("lamp-flame");
  var elLoopWire = document.getElementById("loop-wire");
  var elColonies = document.getElementById("colonies-layer");

  function clamp(n, lo, hi) { return Math.max(lo, Math.min(hi, n)); }

  function setState(next) { state = Object.assign({}, state, next); render(); }

  function render() {
    root.setAttribute("data-step", state.step);
    var meta = STEP_META[state.step];
    elStepTitle.textContent = meta.title;
    elInstruction.textContent = meta.instruction;
    elWhyText.textContent = meta.why;

    var idx = STEP_ORDER.indexOf(state.step);
    var pct = state.step === "complete" ? 100 : Math.round((idx) / 6 * 100);
    elProgressFill.style.width = pct + "%";
    elProgressText.textContent = state.step === "complete"
      ? "Complete"
      : "Step " + (idx + 1) + " of 6";

    // enable/disable action buttons
    var btns = document.querySelectorAll("#actions .btn[data-action]");
    btns.forEach(function (b) {
      var a = b.getAttribute("data-action");
      b.disabled = (a !== state.step && state.step !== "complete");
    });

    // equipment visual states
    setEquipState("loop", state.loopSterile ? "done" : "");
    setEquipState("lamp", "");
    setEquipState("broth", "");
    setEquipState("plate", state.plateSpread ? "done" : "");

    // loop wire color reflects sterility/load
    if (elLoopWire) {
      elLoopWire.setAttribute("stroke", state.loopLoaded ? "#e0c060" : (state.loopSterile ? "#ff8a5a" : "#b8bdc1"));
    }
    // lamp flame on while sterilize is current or done? keep flame always lit.
