  <div class="progress-wrap" data-testid="progress">
    <span class="progress-label" id="progress-text">Step 1 of 6</span>
    <div class="progress-track"><div class="progress-fill" id="progress-fill"></div></div>
  </div>

  <div class="stage">
    <div class="bench" id="bench">
      <div class="sterile-zone drop-target" id="sterile-zone" data-testid="equipment-clean-bench">
        <span class="zone-label">STERILE WORK AREA</span>
      </div>

      <div class="tray left">
        <div class="equipment" data-testid="equipment-inoculation-loop" data-action="drag-loop" draggable="true" id="loop" style="touch-action:none;">
          <!-- Inoculation loop SVG -->
          <svg width="64" height="120" viewBox="0 0 64 120" aria-label="Inoculation loop">
            <defs>
              <linearGradient id="metal" x1="0" x2="1">
                <stop offset="0" stop-color="#cfd6da"/><stop offset=".5" stop-color="#8b949a"/><stop offset="1" stop-color="#5a6166"/>
              </linearGradient>
            </defs>
            <rect x="29" y="40" width="6" height="78" rx="3" fill="url(#metal)" stroke="#3a3f43" stroke-width="1"/>
            <rect x="27" y="2" width="10" height="42" rx="5" fill="#6b4a2a" stroke="#4a3318" stroke-width="1"/>
            <circle cx="32" cy="14" r="5.5" fill="none" stroke="#9aa0a4" stroke-width="2.2"/>
            <path id="loop-wire" d="M32 19 q-9 -3 -9 6 q0 9 9 6" fill="none" stroke="#b8bdc1" stroke-width="2"/>
          </svg>
          <span class="eq-label">Inoculation loop</span>
        </div>

        <div class="equipment" data-testid="equipment-alcohol-lamp" data-action="drag-lamp" draggable="true" id="lamp" style="touch-action:none;">
          <!-- Alcohol lamp SVG with flame + warning -->
          <svg width="80" height="120" viewBox="0 0 80 120" aria-label="Alcohol lamp">
            <defs>
              <radialGradient id="flame" cx=".5" cy="1" r="1">
                <stop offset="0" stop-color="#fff7c2"/><stop offset=".4" stop-color="#ffb347"/><stop offset="1" stop-color="#3a7bd5" stop-opacity="0"/>
              </radialGradient>
              <linearGradient id="glass" x1="0" x2="1">
                <stop offset="0" stop-color="#d8e6ef"/><stop offset=".5" stop-color="#9fc2d4"/><stop offset="1" stop-color="#6f97aa"/>
              </linearGradient>
              <linearGradient id="liquid" x1="0" x2="0" y1="0" y2="1">
                <stop offset="0" stop-color="#bfe3f2"/><stop offset="1" stop-color="#7fb8d6"/>
              </linearGradient>
            </defs>
            <!-- flame -->
            <path id="lamp-flame" d="M40 8 C30 26, 48 30, 40 48 C33 34, 35 22, 40 8 Z" fill="url(#flame)" opacity="0.95"/>
            <ellipse cx="40" cy="50" rx="7" ry="4" fill="#2b4d6b" opacity=".5"/>
            <!-- wick -->
            <rect x="38.5" y="46" width="3" height="14" fill="#3a2a1a"/>
            <!-- cap -->
            <rect x="30" y="58" width="20" height="10" rx="3" fill="#7a8b93" stroke="#4a5660"/>
            <!-- body -->
            <path d="M22 68 Q22 64 26 64 L54 64 Q58 64 58 68 L58 96 Q58 108 40 108 Q22 108 22 96 Z" fill="url(#glass)" stroke="#4a6273" stroke-width="1.5"/>
            <path d="M24 90 Q24 102 40 102 Q56 102 56 90 L56 84 Q40 92 24 84 Z" fill="url(#liquid)" opacity="0.85"/>
            <!-- warning badge -->
            <g transform="translate(54,98)">
              <polygon points="0,-12 12,8 -12,8" fill="#ffcf4a" stroke="#7a5b00" stroke-width="1"/>
              <text x="0" y="3" text-anchor="middle" font-size="10" font-weight="700" fill="#5a3b00">!</text>
            </g>
          </svg>
          <span class="eq-label" style="color:var(--warn)">⚠ Flammable</span>
        </div>
      </div>

      <div class="tray right">
        <div class="equipment" data-testid="equipment-yeast-broth" data-action="drag-broth" draggable="true" id="broth" style="touch-action:none;">
          <!-- Test tube with yeast culture broth + cotton plug -->
          <svg width="46" height="120" viewBox="0 0 46 120" aria-label="Yeast culture broth test tube">
            <defs>
              <linearGradient id="broth-grad" x1="0" x2="0" y1="0" y2="1">
                <stop offset="0" stop-color="#f0d488"/><stop offset="1" stop-color="#c79a3e"/>
              </linearGradient>
              <linearGradient id="tube-glass" x1="0" x2="1">
                <stop offset="0" stop-color="#eaf6f6"/><stop offset=".5" stop-color="#bfe0e0"/><stop offset="1" stop-color="#8fc2c2"/>
              </linearGradient>
            </defs>
            <!-- cotton plug -->
            <ellipse id="cotton-plug-svg" cx="23" cy="10" rx="11" ry="7" fill="#f3efe6" stroke="#cdbfa6"/>
            <path d="M12 10 q11 -8 22 0" fill="#fbf8f1" stroke="#d8cdb6"/>
            <!-- tube body -->
            <path d="M14 16 L14 96 Q14 110 23 110 Q32 110 32 96 L32 16 Z" fill="url(#tube-glass)" stroke="#5f9090" stroke-width="1.5" opacity="0.92"/>
            <!-- broth -->
            <path d="M15 50 L15 96 Q15 108 23 108 Q31 108 31 96 L31 50 Z" fill="url(#broth-grad)" opacity="0.9"/>
            <!-- yeast specks -->
            <circle cx="20" cy="70" r="1.4" fill="#8a6a20"/>
            <circle cx="25" cy="82" r="1.2" fill="#8a6a20"/>
            <circle cx="22" cy="92" r="1.5" fill="#8a6a20"/>
            <circle cx="27" cy="64" r="1" fill="#8a6a20"/>
            <!-- glass highlight -->
            <rect x="16" y="22" width="3" height="60" rx="1.5" fill="#fff" opacity="0.35"/>
          </svg>
          <span class="eq-label">Yeast broth</span>
        </div>

        <div class="equipment" data-testid="equipment-agar-plate" data-action="drag-plate" draggable="true" id="plate" style="touch-action:none;">
          <!-- Agar plate (petri dish) SVG -->
          <svg width="120" height="60" viewBox="0 0 120 60" aria-label="Agar plate">
            <defs>
              <radialGradient id="agar" cx=".5" cy=".5" r=".6">
                <stop offset="0" stop-color="#d9605a"/><stop offset=".7" stop-color="#b8443b"/><stop offset="1" stop-color="#8c2f28"/>
              </radialGradient>
              <linearGradient id="lid" x1="0" x2="0" y1="0" y2="1">
                <stop offset="0" stop-color="#eaf6f6" stop-opacity="0.5"/><stop offset="1" stop-color="#bfe0e0" stop-opacity="0.25"/>
              </linearGradient>
            </defs>
            <ellipse cx="60" cy="34" rx="52" ry="20" fill="#bfe0e0" stroke="#5f9090" stroke-width="1.5"/>
            <ellipse cx="60" cy="32" rx="48" ry="17" fill="url(#agar)"/>
            <ellipse id="colonies-layer" cx="60" cy="32" rx="48" ry="17" fill="transparent"/>
            <ellipse cx="60" cy="30" rx="50" ry="18" fill="url(#lid)"/>
          </svg>
          <span class="eq-label">Agar plate</span>
        </div>

        <div class="equipment" data-testid="equipment-cotton-plug" data-action="drag-cotton" draggable="true" id="cotton" style="touch-action:none;">
          <!-- Standalone cotton plug SVG -->
          <svg width="50" height="60" viewBox="0 0 50 60" aria-label="Cotton plug">
            <ellipse cx="25" cy="30" rx="20" ry="18" fill="#f3efe6" stroke="#cdbfa6" stroke-width="1.2"/>
            <path d="M8 28 q17 -14 34 0 q-17 10 -34 0" fill="#fbf8f1" stroke="#d8cdb6"/>
            <circle cx="18" cy="24" r="2" fill="#e7ddc8"/>
            <circle cx="30" cy="32" r="2.5" fill="#e7ddc8"/>
            <circle cx="24" cy="20" r="1.6" fill="#e7ddc8"/>
          </svg>
          <span class="eq-label">Cotton plug</span>
        </div>
      </div>
    </div>
  </div>

  <div class="info-row">
    <div class="card">
      <div class="step-title" id="step-title">Step 1 — Sterilize</div>
      <div class="step-instruction" data-testid="step-instruction" id="step-instruction">
        Sterilize the inoculation loop in the alcohol lamp flame until red-hot.
      </div>
      <div class="feedback" data-testid="feedback" id="feedback">Drag the loop to the flame, or use the buttons below.</div>

      <div class="contam-meter" style="margin-top:8px;">
        <span>Contamination risk</span>
        <div class="contam-bar"><div class="contam-fill" id="contam-fill" style="width:15%"></div></div>
        <span id="contam-pct">15%</span>
      </div>

      <div class="actions" id="actions">
        <button class="btn primary" data-action="sterilize">🔥 Sterilize loop</button>
        <button class="btn" data-action="cool" disabled>❄️ Cool loop</button>
        <button class="btn" data-action="sample" disabled>🧪 Sample culture</button>
        <button class="btn" data-action="inoculate" disabled>🦠 Inoculate plate</button>
        <button class="btn" data-action="spread" disabled>↔️ Spread sample</button>
        <button class="btn" data-action="incubate" disabled>🌡️ Incubate</button>
      </div>
      <div class="btn-row">
        <button class="btn reset" data-action="reset" id="reset-btn">↻ Reset</button>
      </div>
    </div>

    <div class="card why-box" id="why-box">
      <h3>Why this step matters</h3>
      <p id="why-text">Flaming the loop incinerates any microbes on the wire, so you don't introduce contamination when you touch the culture.</p>
    </div>
