  <div class="enhance">
    <div class="card" id="growth-card">
      <h3 style="margin:0 0 6px;color:var(--accent);font-size:14px;">🔬 Time-lapse colony growth</h3>
      <p style="font-size:13px;color:var(--ink-dim);margin:0 0 8px;" id="growth-status">Complete the experiment to watch colonies grow.</p>
      <div id="growth-controls" class="hidden">
        <button class="btn primary" id="timelapse-btn" data-action="timelapse">▶ Play time-lapse</button>
      </div>
    </div>

    <div class="card" id="quiz-card">
      <h3 style="margin:0 0 8px;color:var(--amber);font-size:14px;">📝 Quick check</h3>
      <div id="quiz-area"></div>
      <div class="quiz-score" id="quiz-score"></div>
    </div>
  </div>

  <footer>Virtual Spread Plate Lab · Original SVG artwork · No external assets</footer>
</div>

<script>
(function () {
  "use strict";

  var STEP_ORDER = ["sterilize", "cool", "sample", "inoculate", "spread", "incubate", "complete"];

  var STEP_META = {
    sterilize: {
      title: "Step 1 — Sterilize",
      instruction: "Sterilize the inoculation loop in the alcohol lamp flame until red-hot.",
      why: "Flaming the loop incinerates any microbes on the wire, so you don't introduce contamination when you touch the culture.",
      actionLabel: "🔥 Sterilize loop"
    },
    cool: {
      title: "Step 2 — Cool",
      instruction: "Cool the sterilized loop by holding it briefly in the sterile work area.",
      why: "A red-hot loop would kill the yeast you're trying to culture. Letting it cool prevents splattering and cell death.",
      actionLabel: "❄️ Cool loop"
    },
    sample: {
      title: "Step 3 — Sample",
      instruction: "Dip the cooled, sterile loop into the yeast culture broth to pick up cells.",
      why: "The loop carries a thin film of liquid. A sterile loop ensures only the intended yeast is transferred.",
      actionLabel: "🧪 Sample culture"
    },
    inoculate: {
      title: "Step 4 — Inoculate",
      instruction: "Touch the loaded loop to the agar surface to deposit the yeast sample.",
      why: "You place a small drop on the agar so it can be spread evenly in the next step.",
      actionLabel: "🦠 Inoculate plate"
    },
    spread: {
      title: "Step 5 — Spread",
      instruction: "Spread the sample evenly across the agar surface using the loop.",
      why: "Even spreading separates cells so they grow into isolated colonies you can count — the whole point of a spread plate.",
      actionLabel: "↔️ Spread sample"
    },
    incubate: {
      title: "Step 6 — Incubate",
      instruction: "Place the plate in the incubator and let the colonies grow.",
      why: "At the right temperature, each viable yeast cell multiplies into a visible colony. Incubation time lets you count results.",
      actionLabel: "🌡️ Incubate"
    },
    complete: {
      title: "Complete",
      instruction: "Experiment complete! Review your results and the time-lapse growth below.",
      why: "Well-separated colonies mean good aseptic technique. Overlapping colonies suggest poor spreading or contamination.",
      actionLabel: ""
    }
  };

  var state = {
    step: "sterilize",
    completed: false,
    history: [],
    contam: 15,
    loopSterile: false,
    loopHot: false,
    loopLoaded: false,
    plateInoculated: false,
    plateSpread: false
  };

  var root = document.getElementById("lab-root");
  var elStepTitle = document.getElementById("step-title");
  var elInstruction = document.getElementById("step-instruction");
  var elFeedback = document.getElementById("feedback");
  var elProgressFill = document.getElementById("progress-fill");
  var elProgressText = document.getElementById("progress-text");
  var elWhyText = document.getElementById("why-text");
  var elContamFill = document.getElementById("contam-fill");
  var elContamPct = document.getElementById("contam-pct");
  var elGrowthStatus = document.getElementById("growth-status");
  var elGrowthControls = document.getElementById("growth-controls");
  var elLampFlame = document.getElementById("lamp-flame");
  var elLoopWire = document.getElementById("loop-wire");
  var elColonies = document.getElementById("colonies-layer");

  function clamp(n, lo, hi) { return Math.max(lo, Math.min(hi, n)); }

  function setState(next) { state = Object.assign({}, state, next); render(); }

  function render() {
    root.setAttribute("data-step", state.step);
    var meta = STEP_META[state.step];
    elStepTitle.textContent = meta.title;
    elInstruction.textContent = meta.instruction;
    elWhyText.textContent = meta.why;

    var idx = STEP_ORDER.indexOf(state.step);
    var pct = state.step === "complete" ? 100 : Math.round((idx) / 6 * 100);
    elProgressFill.style.width = pct + "%";
    elProgressText.textContent = state.step === "complete"
      ? "Complete"
      : "Step " + (idx + 1) + " of 6";

    // enable/disable action buttons
    var btns = document.querySelectorAll("#actions .btn[data-action]");
    btns.forEach(function (b) {
      var a = b.getAttribute("data-action");
      b.disabled = (a !== state.step && state.step !== "complete");
    });

    // equipment visual states
    setEquipState("loop", state.loopSterile ? "done" : "");
    setEquipState("lamp", "");
    setEquipState("broth", "");
    setEquipState("plate", state.plateSpread ? "done" : "");

    // loop wire color reflects sterility/load
    if (elLoopWire) {
      elLoopWire.setAttribute("stroke", state.loopLoaded ? "#e0c060" : (state.loopSterile ? "#ff8a5a" : "#b8bdc1"));
    }
    // lamp flame on while sterilize is current or done? keep flame always lit.
    if (elLampFlame) elLampFlame.setAttribute("opacity", "0.95");

    // contamination
    elContamFill.style.width = state.contam + "%";
    elContamPct.textContent = state.contam + "%";

    // growth card
    if (state.step === "complete") {
      elGrowthStatus.textContent = "Colonies grew! Press play to watch the time-lapse.";
      elGrowthControls.classList.remove("hidden");
    } else {
      elGrowthStatus.textContent = "Complete the experiment to watch colonies grow.";
      elGrowthControls.classList.add("hidden");
    }
  }

  function setEquipState(id, cls) {
    var el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("active", "done");
    if (cls) el.classList.add(cls);
  }

  function setFeedback(msg, kind) {
    elFeedback.textContent = msg;
    elFeedback.classList.remove("ok", "err");
    if (kind) elFeedback.classList.add(kind);
  }

  // ---- Public API ----
  function getState() {
    return {
      step: state.step,
      completed: state.completed,
      history: state.history.slice()
    };
  }

  function perform(action) {
    if (STEP_ORDER.indexOf(action) < 0) {
      var m = "Unknown action: " + action + ". Try: sterilize, cool, sample, inoculate, spread, incubate.";
      setFeedback(m, "err");
      return { ok: false, message: m };
    }
    if (state.step === "complete") {
      var cm = "The experiment is already complete. Press Reset to start again.";
      setFeedback(cm, "err");
      return { ok: false, message: cm };
    }
    if (action !== state.step) {
      var expected = STEP_META[state.step];
      var wmsg = "Not yet! Right now you should: " + expected.instruction.toLowerCase();
      setFeedback(wmsg, "err");
      return { ok: false, message: wmsg };
    }
    // action === current step → success
    return advanceStep(action);
  }

  function advanceStep(action) {
    var meta = STEP_META[action];
    var okMsg = meta.actionLabel.replace(/^[^\s]+\s/, "") + " done. ";
    var effects = {};

    switch (action) {
      case "sterilize":
        effects.loopSterile = true;
        effects.loopHot = true;
        effects.loopLoaded = false;
        okMsg = "The loop is sterile and red-hot. Remember: it must cool before touching the culture.";
        break;
      case "cool":
        effects.loopHot = false;
        okMsg = "Loop cooled in the sterile zone. It's safe to use on the culture now.";
        break;
      case "sample":
        if (!state.loopSterile || state.loopHot) {
          // shouldn't happen because step guards, but be safe
          var sm = "Sterilize and cool the loop first.";
          setFeedback(sm, "err");
          return { ok: false, message: sm };
        }
        effects.loopLoaded = true;
        okMsg = "You've picked up a film of yeast culture. Now deposit it on the agar.";
        break;
      case "inoculate":
        effects.loopLoaded = false;
        effects.plateInoculated = true;
        okMsg = "Sample deposited on the agar. Now spread it evenly.";
        break;
      case "spread":
        effects.plateSpread = true;
        effects.contam = clamp(state.contam - 2, 0, 100);
        okMsg = "Sample spread across the plate. Cells are now separated for colony growth.";
        break;
      case "incubate":
        effects.completed = true;
        effects.contam = clamp(state.contam - 3, 0, 100);
        okMsg = "Incubation complete. Distinct colonies have formed on the agar.";
        break;
    }

    state.step = nextStep(action);
    state.history = state.history.concat([action]);
    state = Object.assign({}, state, effects);
    render();
    if (action === "incubate") {
      drawColonies();
      setFeedback(okMsg, "ok");
      renderQuiz();
    } else {
      setFeedback(okMsg, "ok");
    }
    return { ok: true, message: okMsg };
  }

  function nextStep(current) {
    var i = STEP_ORDER.indexOf(current);
    return STEP_ORDER[Math.min(i + 1, STEP_ORDER.length - 1)];
  }

  function reset() {
    state = {
      step: "sterilize",
      completed: false,
      history: [],
      contam: 15,
      loopSterile: false,
      loopHot: false,
      loopLoaded: false,
      plateInoculated: false,
      plateSpread: false
    };
    clearColonies();
    elFeedback.classList.remove("ok", "err");
    elFeedback.textContent = "Experiment reset. Start by sterilizing the loop.";
    render();
    resetQuiz();
    return { ok: true, message: "Lab reset to the starting state." };
  }

  // ---- Colonies (time-lapse) ----
  var colonyTimer = null;
  function clearColonies() {
    if (colonyTimer) { clearInterval(colonyTimer); colonyTimer = null; }
    while (elColonies.firstChild) elColonies.removeChild(elColonies.firstChild);
    elGrowthStatus.textContent = "Complete the experiment to watch colonies grow.";
    elGrowthControls.classList.add("hidden");
  }

  function drawColonies() {
    // ensure container is set up; actual growth plays on time-lapse
    while (elColonies.firstChild) elColonies.removeChild(elColonies.firstChild);
    // predefine colonies (cx, cy, maxR)
    var defs = [];
    var n = 14 + Math.floor(Math.random() * 6);
    for (var i = 0; i < n; i++) {
      var ang = Math.random() * Math.PI * 2;
      var rad = Math.random() * 0.85;
      defs.push({
        cx: 60 + Math.cos(ang) * rad * 46,
        cy: 32 + Math.sin(ang) * rad * 16,
        maxR: 1.6 + Math.random() * 2.4
      });
    }
    elColonies._defs = defs;
    // show small dots immediately
    defs.forEach(function (d) {
      var c = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      c.setAttribute("cx", d.cx); c.setAttribute("cy", d.cy); c.setAttribute("r", 0.6);
      c.setAttribute("fill", "#f3ead0"); c.setAttribute("opacity", 0.8);
      c._maxR = d.maxR;
      elColonies.appendChild(c);
    });
  }

  function playTimeLapse() {
    var defs = elColonies._defs || [];
    if (!defs.length) return;
    var circles = elColonies.querySelectorAll("circle");
    var frame = 0;
    var totalFrames = 24;
    if (colonyTimer) clearInterval(colonyTimer);
    colonyTimer = setInterval(function () {
      frame++;
      var t = frame / totalFrames;
      circles.forEach(function (c) {
        var r = clamp(t * c._maxR, 0.6, c._maxR);
        c.setAttribute("r", r);
        c.setAttribute("opacity", 0.5 + 0.5 * t);
      });
      elGrowthStatus.textContent = "Day " + Math.ceil(t * 3) + " — colonies growing…";
      if (frame >= totalFrames) {
        clearInterval(colonyTimer); colonyTimer = null;
        elGrowthStatus.textContent = "Day 3 — mature colonies. Count the distinct ones!";
      }
    }, 220);
  }

  // ---- Quiz ----
  var QUIZ = [
    {
      q: "Why sterilize the loop before sampling?",
      opts: ["To make it shiny", "To kill microbes so they aren't introduced", "To heat the broth", "It isn't necessary"],
      answer: 1
    },
    {
      q: "What can happen if the loop is still hot when it touches the culture?",
      opts: ["Nothing", "Better growth", "It kills the yeast cells", "The agar melts"],
      answer: 2
    },
    {
      q: "Why spread the sample across the agar?",
      opts: ["To dry the plate", "To separate cells into isolated colonies", "To sterilize it", "To add nutrients"],
      answer: 1
    }
  ];
  var quizAnswered = {};

  function renderQuiz() {
    var area = document.getElementById("quiz-area");
    area.innerHTML = "";
    QUIZ.forEach(function (item, i) {
      var div = document.createElement("div");
      div.className = "quiz-q";
      var q = document.createElement("div"); q.className = "q"; q.textContent = (i + 1) + ". " + item.q;
      div.appendChild(q);
      var opts = document.createElement("div"); opts.className = "quiz-opts";
      item.opts.forEach(function (o, j) {
        var b = document.createElement("button");
        b.className = "quiz-opt"; b.textContent = o;
        b.setAttribute("data-action", "quiz");
        b.addEventListener("click", function () {
          if (quizAnswered[i]) return;
          quizAnswered[i] = j;
          if (j === item.answer) b.classList.add("correct");
          else b.classList.add("wrong");
          // reveal correct
          Array.prototype.forEach.call(opts.children, function (ch, k) {
            if (k === item.answer) ch.classList.add("correct");
            ch.style.cursor = "default";
          });
          updateQuizScore();
        });
        opts.appendChild(b);
      });
      div.appendChild(opts);
      area.appendChild(div);
    });
    document.getElementById("quiz-score").textContent = "";
  }

  function resetQuiz() {
    quizAnswered = {};
    renderQuiz();
  }

  function updateQuizScore() {
    var correct = 0, total = QUIZ.length, answered = 0;
    QUIZ.forEach(function (item, i) {
      if (quizAnswered[i] !== undefined) {
        answered++;
        if (quizAnswered[i] === item.answer) correct++;
      }
    });
    var score = document.getElementById("quiz-score");
    score.textContent = answered ? (correct + " / " + answered + " correct" + (answered === total ? " — done!" : "")) : "";
  }

  renderQuiz();

  // ---- Button wiring ----
  document.querySelectorAll('[data-action]').forEach(function (el) {
    if (el.id === "timelapse-btn") {
      el.addEventListener("click", playTimeLapse);
      return;
    }
    if (el.classList.contains("quiz-opt")) return; // handled above
    var action = el.getAttribute("data-action");
    if (STEP_ORDER.indexOf(action) >= 0 || action === "reset") {
      el.addEventListener("click", function () {
        if (action === "reset") reset();
        else perform(action);
      });
    }
  });

  // ---- Drag interactions (pointer-based, touch-friendly) ----
  // Map: which equipment, when dropped on a target, triggers which action.
  var DROP_MAP = {
    loop: {
      lamp: "sterilize",
      "sterile-zone": "cool",
      broth: "sample",
      plate: state.plateInoculated ? "spread" : "inoculate"
    }
  };

  function getDropAction(dragId, dropId) {
    var map = DROP_MAP[dragId];
    if (!map) return null;
    if (dropId === "plate") {
      // context-sensitive: inoculate first, then spread
      if (state.step === "inoculate") return "inoculate";
      if (state.step === "spread") return "spread";
    }
    return map[dropId] || null;
  }

  var dragState = null;
  var equipmentEls = ["loop", "lamp", "broth", "plate", "cotton"];

  equipmentEls.forEach(function (id) {
    var el = document.getElementById(id);
    if (!el) return;
    // native dragstart (for desktop drag) — we also use pointer for full control
    el.addEventListener("dragstart", function (e) {
      // let pointer-based system handle; prevent default ghost for consistency
      try { e.dataTransfer.setData("text/plain", id); e.dataTransfer.effectAllowed = "move"; } catch (_) {}
      dragState = { id: id, el: el, via: "native" };
    });

    // pointer-based drag
    el.addEventListener("pointerdown", function (e) {
      if (e.pointerType === "mouse" && e.button !== 0) return;
      e.preventDefault();
      var rect = el.getBoundingClientRect();
      var parentRect = el.offsetParent ? el.offsetParent.getBoundingClientRect() : rect;
      dragState = {
        id: id,
        el: el,
        startX: e.clientX,
        startY: e.clientY,
        offsetX: e.clientX - rect.left,
        offsetY: e.clientY - rect.top,
        moved: false,
        origTransform: el.style.transform || "",
        via: "pointer"
      };
      el.classList.add("dragging");
      el.setPointerCapture && el.setPointerCapture(e.pointerId);
    });
  });

  document.addEventListener("pointermove", function (e) {
    if (!dragState || dragState.via !== "pointer") return;
    var el = dragState.el;
    var dx = e.clientX - dragState.startX;
    var dy = e.clientY - dragState.startY;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) dragState.moved = true;
    el.style.transform = "translate(" + dx + "px," + dy + "px)";
    // highlight potential drop targets
    highlightDropTarget(e.clientX, e.clientY);
  }, { passive: false });

  document.addEventListener("pointerup", function (e) {
    if (!dragState || dragState.via !== "pointer") return;
    var el = dragState.el;
    el.classList.remove("dragging");
    clearDropHighlights();

    var dropId = findDropTarget(e.clientX, e.clientY);
    el.style.transform = dragState.origTransform;

    if (dragState.moved && dropId) {
      var action = getDropAction(dragState.id, dropId);
      if (action) {
        perform(action);
      } else {
        // dropped on something that isn't a valid target for this item/step
        var meta = STEP_META[state.step];
        setFeedback("That equipment doesn't do anything here. " +
          (meta ? meta.instruction : ""), "err");
      }
    }
    dragState = null;
  });

  document.addEventListener("pointercancel", function () {
    if (dragState && dragState.via === "pointer") {
      dragState.el.classList.remove("dragging");
      dragState.el.style.transform = dragState.origTransform;
      clearDropHighlights();
      dragState = null;
    }
  });

  var dropTargets = ["lamp", "broth", "plate", "sterile-zone"];
  function findDropTarget(x, y) {
    var el = document.elementFromPoint(x, y);
    while (el && el !== document.body) {
      if (el.id && dropTargets.indexOf(el.id) >= 0) return el.id;
      // equipment element id is the wrapper; check data-testid
      if (el.id && equipmentEls.indexOf(el.id) >= 0) return el.id;
      el = el.parentElement;
    }
    return null;
  }

  function highlightDropTarget(x, y) {
    clearDropHighlights();
    var id = findDropTarget(x, y);
    if (id) {
      var t = document.getElementById(id);
      if (t && t.classList.contains("drop-target")) t.classList.add("hover");
      if (t && equipmentEls.indexOf(id) >= 0) t.classList.add("active");
    }
  }

  function clearDropHighlights() {
    document.querySelectorAll(".drop-target.hover").forEach(function (e) { e.classList.remove("hover"); });
    equipmentEls.forEach(function (id) {
      var el = document.getElementById(id);
      if (el) el.classList.remove("active");
    });
    // restore done/sterile visual states
    setEquipState("loop", state.loopSterile ? "done" : "");
    setEquipState("plate", state.plateSpread ? "done" : "");
  }

  // prevent default dragover from blocking native DnD ghost (cosmetic)
  document.addEventListener("dragover", function (e) { e.preventDefault(); });
  document.addEventListener("drop", function (e) {
    e.preventDefault();
    if (dragState && dragState.via === "native") {
      var dropId = findDropTarget(e.clientX, e.clientY);
      if (dropId) {
        var action = getDropAction(dragState.id, dropId);
        if (action) perform(action);
      }
      dragState = null;
    }
  });

  // initial render
  render();

  // expose public API
  window.spreadPlateLab = {
    getState: getState,
    perform: perform,
    reset: reset
  };
})();
</script>
</body>
</html>
"}

