const fs = require("fs");
const path = require("path");
const { JSDOM } = require("/tmp/node_modules/jsdom");

const htmlPath = path.resolve(process.argv[2]);
const html = fs.readFileSync(htmlPath, "utf8");

const dom = new JSDOM(html, {
  runScripts: "dangerously",
  resources: undefined,
  pretendToBeVisual: true,
});
const { window } = dom;

// Wait for the IIFE to run
setTimeout(() => {
  let pass = 0, fail = 0;
  function check(name, cond) {
    if (cond) { pass++; console.log("  ✓ " + name); }
    else { fail++; console.log("  ✗ " + name); }
  }

  const lab = window.spreadPlateLab;
  check("window.spreadPlateLab exists", !!lab);
  check("getState exists", typeof lab.getState === "function");
  check("perform exists", typeof lab.perform === "function");
  check("reset exists", typeof lab.reset === "function");

  // data-testid markers
  const testIds = [
    "lab-root","equipment-yeast-broth","equipment-cotton-plug","equipment-agar-plate",
    "equipment-inoculation-loop","equipment-alcohol-lamp","equipment-clean-bench",
    "step-instruction","feedback","progress"
  ];
  testIds.forEach(id => {
    const el = window.document.querySelector('[data-testid="'+id+'"]');
    check('data-testid="'+id+'"', !!el);
  });

  // lab-root has data-step
  const root = window.document.querySelector('[data-testid="lab-root"]');
  check('lab-root has data-step', root && root.getAttribute("data-step") === "sterilize");

  // draggable on equipment
  ["equipment-yeast-broth","equipment-cotton-plug","equipment-agar-plate","equipment-inoculation-loop","equipment-alcohol-lamp","equipment-clean-bench"].forEach(id=>{
    const el = window.document.querySelector('[data-testid="'+id+'"]');
    check(id+" has draggable=true", el && el.getAttribute("draggable") === "true");
  });

  // data-action buttons (visible = present and not hidden)
  ["sterilize","cool","sample","inoculate","spread","incubate","reset"].forEach(a=>{
    const el = window.document.querySelector('[data-action="'+a+'"]');
    check('data-action="'+a+'" visible', el && !el.classList.contains("hidden") && el.disabled === false || (el && a==="reset"));
  });

  // Initial state
  let s = lab.getState();
  check("initial step sterilize", s.step === "sterilize");
  check("initial completed false", s.completed === false);
  check("initial history empty", Array.isArray(s.history) && s.history.length === 0);

  // Out-of-order: perform('cool') while step=sterilize
  let r = lab.perform("cool");
  check("cool out-of-order ok:false", r.ok === false);
  check("cool out-of-order no advance", lab.getState().step === "sterilize");

  // Unknown action
  r = lab.perform("frobnicate");
  check("unknown action ok:false", r.ok === false);

  // Valid sequence
  r = lab.perform("sterilize");
  check("sterilize ok", r.ok === true && r.message && typeof r.message === "string");
  check("now step cool", lab.getState().step === "cool");
  check("history has sterilize", lab.getState().history[0] === "sterilize");

  lab.perform("cool"); check("now sample", lab.getState().step === "sample");
  lab.perform("sample"); check("now inoculate", lab.getState().step === "inoculate");
  lab.perform("inoculate"); check("now spread", lab.getState().step === "spread");
  lab.perform("spread"); check("now incubate", lab.getState().step === "incubate");
  r = lab.perform("incubate");
  check("incubate ok", r.ok === true);
  check("now complete", lab.getState().step === "complete");
  check("completed true", lab.getState().completed === true);
  check("history length 6", lab.getState().history.length === 6);

  // perform after complete
  r = lab.perform("sterilize");
  check("perform after complete ok:false", r.ok === false);

  // reset
  r = lab.reset();
  check("reset ok", r.ok === true);
  s = lab.getState();
  check("reset step sterilize", s.step === "sterilize");
  check("reset completed false", s.completed === false);
  check("reset history empty", s.history.length === 0);

  // reset return value shape
  check("reset returns message", typeof r.message === "string");

  console.log("\n" + pass + " passed, " + fail + " failed");
  process.exit(fail ? 1 : 0);
}, 200);

