  check("invalid returns ok:false", r2.ok === false);
  check("invalid leaves step unchanged", lab.getState().step === before);
  check("feedback has err class", fb.classList.contains("err"));

  // reset clears visual + state
  lab.reset();
  check("reset step sterilize", lab.getState().step === "sterilize");
  check("root step back to sterilize", root.getAttribute("data-step") === "sterilize");

  // quiz rendered
  const quizOpts = window.document.querySelectorAll('#quiz-area .quiz-opt');
  check("quiz options present (>0)", quizOpts.length > 0);

  // equipment count
  const eqs = ["equipment-yeast-broth","equipment-cotton-plug","equipment-agar-plate","equipment-inoculation-loop","equipment-alcohol-lamp","equipment-clean-bench"];
  eqs.forEach(id => {
    const el = window.document.querySelector('[data-testid="'+id+'"]');
    check(id+" present", !!el);
  });

  console.log("\n" + pass + " passed, " + fail + " failed");
  process.exit(fail ? 1 : 0);
}, 300);

